// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amount, bytes calldata data) public {
        vm.assume(caller != c.owner());
        bool ok;
        vm.prank(caller);
        try c.sendMoney(caller, amount, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "sendMoney should fail for non-owner");
    }
}
